import React, { useState } from 'react';
import axios from 'axios';

function BookingPage() {
  const [slotId, setSlotId] = useState('');
  const [userId, setUserId] = useState('');
  const [bookingDate, setBookingDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [message, setMessage] = useState('');

const handleBooking = async () => {
  try {
    const bookingData = {
  startTime: `${bookingDate}T${startTime}`,
  endTime: `${bookingDate}T${endTime}`,
  vehicleNumber: vehicleNumber.trim(), // send actual input
};


    const response = await axios.post(
      `http://localhost:8080/api/bookings?userId=${userId}&parkingSlotId=${slotId}`,
      bookingData
    );

    if (response.status === 200 || response.status === 201) {
      setMessage('✅ Booking successful');
    } else {
      setMessage('❌ Error creating booking.');
    }
  } catch (error) {
    console.error(error.response?.data || error.message);
    setMessage('❌ Error creating booking.');
  }
};


  return (
    <div>
      <h2>Book a Slot</h2>
      <input type="number" placeholder="Slot ID" value={slotId} onChange={(e) => setSlotId(e.target.value)} />
      <input type="number" placeholder="User ID" value={userId} onChange={(e) => setUserId(e.target.value)} />
      <input type="text" placeholder="Vehicle Number" value={vehicleNumber} onChange={(e) => setVehicleNumber(e.target.value)} />
      <input type="date" value={bookingDate} onChange={(e) => setBookingDate(e.target.value)} />
      <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} />
      <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} />
      <button onClick={handleBooking}>Book Slot</button>
      <p>{message}</p>
    </div>
  );
}

export default BookingPage;
